#include "evaluator.hpp"
#include <algorithm>
namespace exotic::autonomy::governance {
bool AuthorityEvaluator::rule_matches(const PolicyRule&r,const AuthorityContext&c)const{if(!r.action.empty()&&r.action!=c.action)return false;if(!r.resource_type.empty()&&r.resource_type!=c.resource.type)return false;if(static_cast<int>(c.risk)<static_cast<int>(r.minimum_risk))return false;if(!r.required_role.empty()&&std::find(c.subject.roles.begin(),c.subject.roles.end(),r.required_role)==c.subject.roles.end())return false;if(!r.attribute_key.empty()){auto i=c.subject.attributes.find(r.attribute_key);if(i==c.subject.attributes.end()||i->second!=r.attribute_value)return false;}if(r.simulation_only&&!c.simulation)return false;return true;}
AuthorityResult AuthorityEvaluator::evaluate(const AuthorityContext& c){if(repository_.emergency_stop_active())return{false,false,true,"Emergency stop is active",{}};bool grant_ok=false;for(const auto&g:repository_.load_grants(c.subject.id)){if(g.revoked||Clock::now()<g.valid_from||(g.valid_until&&Clock::now()>=*g.valid_until))continue;if(g.capability.action!=c.action||g.capability.resource_type!=c.resource.type)continue;const auto scoped=g.capability.scope=="*"||g.capability.scope==c.resource.id||g.capability.scope==c.resource.type+":"+c.resource.id;if(!scoped)continue;if(static_cast<int>(c.requested_autonomy)>static_cast<int>(g.maximum_autonomy))continue;if(c.budget_usd>g.budget_limit_usd)continue;grant_ok=true;break;}if(!grant_ok)return{false,false,false,"No active capability grant covers action, scope, autonomy, and budget",{}};Effect effect=Effect::Deny;for(const auto&p:repository_.load_active_policies())for(const auto&r:p.rules)if(rule_matches(r,c)){if(r.effect==Effect::Deny)return{false,false,false,"Denied by policy "+p.name+":"+r.id,{}};if(r.effect==Effect::Escalate)effect=Effect::Escalate;else if(effect!=Effect::Escalate)effect=Effect::Allow;}if(c.simulation)return{true,false,false,"Simulation-only execution authorized",{}};if(c.risk>=RiskLevel::High||c.requested_autonomy==AutonomyLevel::ExecuteWithApproval||effect==Effect::Escalate)return{false,true,false,"Durable approval required",{}};return{effect==Effect::Allow,false,false,effect==Effect::Allow?"Authority granted":"No allowing policy matched",{}};}
}
